InterfaceAsPlainText.xhtml:
VAR_GLOBAL

    // ---------- DIGITAL INPUTS ----------
	(* Buttons *)
    StartButton_In      : BOOL;
    StopButton_In       : BOOL;
    ResetButton_In      : BOOL;
    Emergency_In        : BOOL;     // NC contact -> TRUE = OK

	(* Switchs *)
	ManualMode_Sw			: BOOL;
	AutoMode_Sw				: BOOL;			

    // ---------- DIGITAL OUTPUTS ----------
    (* Lamp *)
	RunLamp_Out       	: BOOL;
	ReadyLamp_Out		: BOOL;
    AlarmLamp_Out       : BOOL;


    // ---------- VIRTUAL MASTER ----------
    MasterAxis  : MOIN.FB_ControlledAxis;

    // ---------- REAL AXES ----------
    MainChain   : MOIN.FB_ControlledAxis;   // DRV1
    Conveyor    : MOIN.FB_ControlledAxis;   // DRV2
    CutterAxis  : MOIN.FB_ControlledAxis;   // DRV3

END_VAR

VAR_GLOBAL

    // ---------- ALARMS ----------
    Alarms      : AlarmSystem;

    // ---------- DATE / TIME ----------
    Clock       : TimeData;
    TimeRead    : BOOL;     // <- HMI button "Load"
    TimeWrite   : BOOL;     // <- HMI button "Apply"

	// --------- SYSTEM --------------
	Machine		: MachineStatus;
END_VAR

VAR_GLOBAL

	IS_DEBUG: BOOL := TRUE;	
END_VAR

ST.xhtml:
// Rising edge 0 -> 1
Pressed := Signal AND NOT State;

// Falling edge 1 -> 0
Released := NOT Signal AND State;

// Save Current state
State := Signal;

InterfaceAsPlainText.xhtml:
FUNCTION_BLOCK AlarmSystem
VAR_INPUT
    Reset       : BOOL;
END_VAR
VAR_OUTPUT
    Active      : BOOL;                         // -> HMI lamp
    Count       : UINT;                         // -> HMI
    ActiveList  : ARRAY [1..20] OF UINT;        // -> HMI list
END_VAR
VAR
    Cond        : ARRAY [1..100] OF BOOL;
    Latch       : ARRAY [1..100] OF BOOL;
    ResetTrig   : R_TRIG;
    BuzzerTon   : TON;
    BuzzerLtc   : BOOL;
    i           : UINT;
    idx         : UINT;
END_VAR

FUNCTION_BLOCK AlarmSystem
VAR_INPUT
    Reset       : BOOL;
END_VAR
VAR_OUTPUT
    Active      : BOOL;                         // -> HMI lamp
    Count       : UINT;                         // -> HMI
    ActiveList  : ARRAY [1..20] OF UINT;        // -> HMI list
END_VAR
VAR
    Cond        : ARRAY [1..100] OF BOOL;
    Latch       : ARRAY [1..100] OF BOOL;
    ResetTrig   : R_TRIG;
    BuzzerTon   : TON;
    BuzzerLtc   : BOOL;
    i           : UINT;
    idx         : UINT;
END_VAR

FUNCTION_BLOCK AlarmSystem
VAR_INPUT
    Reset       : BOOL;
END_VAR
VAR_OUTPUT
    Active      : BOOL;                         // -> HMI lamp
    Count       : UINT;                         // -> HMI
    ActiveList  : ARRAY [1..20] OF UINT;        // -> HMI list
END_VAR
VAR
    Cond        : ARRAY [1..100] OF BOOL;
    Latch       : ARRAY [1..100] OF BOOL;
    ResetTrig   : R_TRIG;
    BuzzerTon   : TON;
    BuzzerLtc   : BOOL;
    i           : UINT;
    idx         : UINT;
END_VAR

ST.xhtml:
// CALL LAST, AFTER ALL Chk() CALLS

ResetTrig(CLK := Reset);

Count := 0;
idx   := 0;

FOR i := 1 TO 100 DO

    // reset clears only alarms whose condition is gone
    IF ResetTrig.Q AND NOT Cond[i] THEN
        Latch[i] := FALSE;
    END_IF

    IF Latch[i] THEN
        Count := Count + 1;
        IF idx < 20 THEN
            idx := idx + 1;
            ActiveList[idx] := i;
        END_IF
    END_IF

END_FOR

FOR i := idx + 1 TO 20 DO
    ActiveList[i] := 0;
END_FOR

Active := (Count > 0);

IF ResetTrig.Q THEN
    BuzzerLtc := FALSE;
END_IF

BuzzerTon(IN := BuzzerLtc, PT := T#5S);

IF BuzzerTon.Q THEN
    BuzzerLtc := FALSE;
END_IF

InterfaceAsPlainText.xhtml:
METHOD PUBLIC  Chk
VAR_INPUT
    ID      : UINT;
    Alarm   : BOOL;
END_VAR

ST.xhtml:
IF (ID < 1) OR (ID > 100) THEN
    RETURN;
END_IF

Cond[ID] := Alarm;

IF Alarm AND NOT Latch[ID] THEN
    Latch[ID] := TRUE;
    BuzzerLtc := TRUE;
END_IF

