END_VAR

PROGRAM DateTime
VAR
    RTCget      : DWORD;
    SetTime     : DWORD;
    pRes        : SysTimeRtc.RTS_IEC_RESULT;
    TimeLoaded  : BOOL;
END_VAR

ST.xhtml:
// ---------- READ RTC ----------
SysTimeRtc.SysTimeRtcConvertUtcToDate(dwTimestampUtc := RTCget, pDate := Clock.Act);
SysTimeRtc.SysTimeRtcGet(pResult := pRes, SysTimeRtcGet => RTCget);

// ---------- LOAD CURRENT TIME INTO EDIT FIELDS ----------
IF TimeRead THEN
    Clock.Set  := Clock.Act;
    TimeRead   := FALSE;
    TimeLoaded := TRUE;
END_IF

// ---------- WRITE RTC ----------
IF TimeWrite AND TimeLoaded THEN
    SysTimeRtc.SysTimeRtcConvertDateToUtc(pDate := Clock.Set, pdwTimestampUtc := SetTime);
    SysTimeRtc.SysTimeRtcSet(ulTimestamp := SetTime);
    TimeWrite  := FALSE;
    TimeLoaded := FALSE;
END_IF

InterfaceAsPlainText.xhtml:
PROGRAM DateTime
VAR
    RTCget      : DWORD;
    SetTime     : DWORD;
    pRes        : SysTimeRtc.RTS_IEC_RESULT;
    TimeLoaded  : BOOL;
END_VAR

PROGRAM Main
VAR
	startButton		:	Button;
	stopButton		:	Button;
	reset		:	Emergency;
	emergencyStop	:	Emergency;


    // ---------- MASTER ----------
    MasterPower     : PLCO.MC_Power;
    MasterHome      : PLCO.MC_Home;
    MasterRun       : PLCO.MC_MoveVelocity;
    MasterStop      : PLCO.MC_Stop;

    // ---------- MOTOR 1 ----------
    M1Power         : PLCO.MC_Power;
    M1Home          : PLCO.MC_Home;
    M1Reset         : PLCO.MC_Reset;
    M1GearIn        : PLCO.MC_GearIn;
    M1Run           : PLCO.MC_MoveVelocity;
    M1Stop          : PLCO.MC_Stop;

    // ---------- MOTOR 2 ----------
    M2Power         : PLCO.MC_Power;
    M2Home          : PLCO.MC_Home;
    M2Reset         : PLCO.MC_Reset;
    M2GearIn        : PLCO.MC_GearIn;

	  // ---------- SETTINGS ----------
    Motor1Speed : LREAL := 50.0;    // deg/s   <- HMI
    Motor1Accel : LREAL := 200.0;
    Motor1Decel : LREAL := 200.0;

    // ---------- STATUS ----------
    Motor1Pos   : LREAL;            // -> HMI
END_VAR

ST.xhtml:
// Define Elements.

startButton(
	signal	:=	StartButton_In // start button OR from HMI or start button2 ... NO
);

stopButton(
	signal	:=	StopButton_In 	// stop button OR HMI or stop button2 ... NO
);

emergencyStop(
	Signal	:=	Emergency_In	// button1 AND button2 AND button3 NC
);

reset(
	signal := ResetButton_In	// from FSR .. normal Close NC.
);

Alarms.Chk(  1, emergencyStop.Active          );  // Emergency Stop

// 100 .. System logic 

// 200 .. Sensors

// 400 .. > 499 Motors Drivers
Alarms.Chk( 41, (DRV1.Axis.etAxisState = 0)     );  // Motor 1 Fault

// ---- RUN  ----
Alarms( Reset := reset.Active );

Machine.Ready    := Machine.SafetyOk
                    AND Machine.BusOk
                    AND Machine.PowerOk
                    AND Machine.HomeOk
                    AND Machine.AxisOk
                    AND NOT Alarms.Active;

Machine.ResetRequest	:= Alarms.Active OR reset.Active;
// must be later in FB for machine status so its auto do this.. Machine.StopRequest		:= 
IF IS_DEBUG THEN
	Machine.Ready := TRUE;
	Machine.Running:= TRUE;

	AutoMode_Sw :=TRUE;

	StartButton_In :=TRUE;
	Emergency_In:= TRUE;
	StopButton_In :=FALSE;
	ResetButton_In :=TRUE;
END_IF

// ---------- MODE ----------
Machine.ManualMode := ManualMode_Sw;
Machine.AutoMode := AutoMode_Sw  AND NOT Machine.ManualMode;


// ---------- START / STOP ----------
IF StartButton.Pressed AND Machine.Ready AND (Machine.AutoMode OR Machine.ManualMode) THEN
    Machine.Running := TRUE;
END_IF

IF StopButton.Pressed OR NOT Machine.Ready THEN
    Machine.Running := FALSE;
END_IF

// ---------- Lamps ----------
AlarmLamp_Out 	:= Alarms.Active;
RunLamp_Out  	:= Machine.Running;
ReadyLamp_Out	:= Machine.Ready AND NOT Machine.Running;


// -------------- Call Methods -----------
IF Machine.AutoMode AND Machine.Running THEN
    Main.Run_Automatic();
END_IF

IF Machine.ManualMode AND Machine.Running THEN
    Main.Run_Manual();
END_IF

// --------- CHECK StATUS -----
Machine.AxisOk		:= (DRV1.Axis.etAxisState <> 0);
Machine.BusOk		:= TRUE;
Machine.HomeOk		:= TRUE;
Machine.PowerOk		:= TRUE;
Machine.SafetyOk	:= TRUE;


///========= MOTORS =================
// ---------- RESET ----------
M1Reset( Axis    := DRV1.Axis,
         Execute := Machine.ResetRequest	);

// ---------- POWER ----------
M1Power( Axis   := DRV1.Axis,
         Enable := Machine.Power );

Machine.PowerOk := M1Power.Status;

// ---------- RUN ----------
M1Run( Axis         := DRV1.Axis,
       Execute      := Machine.Running,
       Velocity     := Motor1Speed,
       Acceleration := Motor1Accel,
       Deceleration := Motor1Decel );

// ---------- STOP ----------
M1Stop( Axis         := DRV1.Axis,
        Execute      := NOT Machine.Running,
        Deceleration := Motor1Decel );

// ---------- STATUS ----------
Motor1Pos := DRV1.Axis.lrPosition;

